const output = $('Email classifier agent').first().json;
const requestBody = $('Email classifier request').first().json.body || {};
const agentSettings = requestBody.agent_settings || requestBody.agentSettings || {};
const defaultTopics = ['entradas', 'horarios', 'ubicacion', 'accesibilidad', 'programacion', 'grupos', 'devoluciones', 'partnerships', 'prensa', 'quejas', 'facturacion', 'otro'];
function text(value) {
  if (typeof value === 'string') return value;
  if (Array.isArray(value)) return value.map(text).find(Boolean) || '';
  if (!value || typeof value !== 'object') return '';
  return value.output || value.text || value.output_text || value.content || text(value.message) || text(value.response) || '';
}
function normalizeTopic(value) {
  return String(value || '')
    .trim()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '')
    .slice(0, 48);
}
const configuredTopics = Array.isArray(agentSettings.classificationTopics)
  ? agentSettings.classificationTopics
  : Array.isArray(agentSettings.classification_topics)
    ? agentSettings.classification_topics
    : [];
const allowedTopics = Array.from(new Set((configuredTopics.length ? configuredTopics : defaultTopics).map(normalizeTopic).filter(Boolean)));
if (!allowedTopics.includes('otro')) allowedTopics.push('otro');
function coerceTopic(value) {
  const topic = normalizeTopic(value);
  return allowedTopics.includes(topic) ? topic : 'otro';
}
const raw = String(text(output)).replace(/^```json\s*/i, '').replace(/```$/i, '').trim();
let parsed = {};
try { parsed = raw ? JSON.parse(raw) : {}; } catch {}
const fullText = `${requestBody.subject || ''}\n${requestBody.body_text || requestBody.bodyText || ''}`.normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/\u00b7/g, '').toLowerCase();
const partnershipPattern = /\b(partnership|partner|collaboration|proposal|sponsorship|sponsor|press|media kit|colaboracion|collaboracio|propuesta|proposta|patrocinio|patrocini|prensa|comercial)\b/i;
const isPartnership = partnershipPattern.test(fullText);
const priority = ['low', 'normal', 'high', 'urgent'].includes(parsed.priority) ? parsed.priority : 'normal';
const partnershipTopic = ['partnerships', 'partnership', 'colaboraciones', 'prensa', 'comercial'].find((topic) => allowedTopics.includes(topic));
const topic = isPartnership && partnershipTopic ? partnershipTopic : coerceTopic(parsed.topic || parsed.category || parsed.intent);
return [{ json: {
  should_process: isPartnership ? true : parsed.should_process !== false,
  should_reply: isPartnership ? true : parsed.should_reply === true,
  needs_human_review: isPartnership ? true : parsed.needs_human_review === true,
  classification_reason: isPartnership ? 'partnership_request' : parsed.classification_reason || parsed.reason || 'other',
  topic,
  priority: isPartnership && priority === 'low' ? 'normal' : priority,
  confidence: typeof parsed.confidence === 'number' ? parsed.confidence : null,
  escalation_reason: isPartnership ? (parsed.escalation_reason || 'partnership_request') : parsed.escalation_reason || null,
  raw_classifier_output: output
}}];
